import AppKit

/// The Color sub-tab's **Wheels** section (spec §11 GR-11, grading-2 G2-2):
/// Lift, Gamma and Gain across one row, each a disc for the colour push, a
/// master strip and a master field.
///
/// Every control writes only its own keys — a puck its wheel's `x, y`, a
/// strip or a field its wheel's `master` — through `binding.ops(video:)`, so a
/// write over several clips keeps each one's other values and lands on an
/// action's end when one is selected. A puck or strip drag is the live trio
/// (one undo step named after the wheel); a field, a double-click and Reset
/// commit once, and a strip's double-click off the knob first undoes its
/// first click's jump, so it too is one step (#272). The row never depends on
/// a value, so a live drag never rebuilds the pane (`structureSignature` is
/// unchanged), and it has one row mark and one mixed badge for the whole
/// `video.wheels` key (CI-7, CI-9).
extension VideoPane {
    // MARK: Wheels

    func wheelsSection() -> InspectorSection {
        let binding = self.binding
        func wheels() -> ColorWheels { binding.videoProps.wheels }
        func ops(_ patch: ColorWheelsPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(wheels: patch))
        }
        let view = ColorWheelsView(binding: binding, wheels: wheels, ops: ops)
        let row = inspectorRow(
            nil, [view], mixed: { binding.mixedVideo { $0.wheels } }, binding: binding,
            writes: ops(.neutral),
            default: .derived(binding, name: "Wheels", read: wheels) { ops(ColorWheelsView.whole($0)) })
        let gutter = row.gutter
        view.keyed = { [weak gutter] in gutter?.isKeyed == true }
        return InspectorSection(
            id: "video.wheels", title: "Wheels",
            summary: { wheels().isNeutral ? "neutral" : "adjusted" },
            reset: { binding.apply("Wheels", video: VideoPatch(wheels: .neutral)) },
            defaultExpanded: false,
            rows: [row])
    }
}

/// The Wheels row's three columns — Lift · Gamma · Gain — each a title, a
/// square-framed `ColorWheelControl`, a `WheelStripControl` and a master
/// field (2 decimals, no unit, −1…1). The disc is the column less 4 pt,
/// capped at 112 pt, so it is about 78 pt at the default pane and 70 at the
/// narrowest. Hugging 1: the row's stretchy element (`inspectorRow` gives it
/// no trailing spacer).
final class ColorWheelsView: NSView {
    static let gap: CGFloat = 4
    static let maxDisc: CGFloat = 112
    /// Whether the row is keyed; the controls ask it when they draw.
    var keyed: () -> Bool = { false }
    private(set) var discs: [ColorWheelControl] = []
    private(set) var strips: [WheelStripControl] = []
    /// `document.project` at each strip's press, while its gesture runs.
    private var stripStarts: [ColorWheelKind: ReelProject] = [:]
    /// `document.project` after each strip's release, and when, kept only
    /// when the gesture made a step (#272): the step a double-click's reset
    /// amends.
    private var stripSteps: [ColorWheelKind: (step: ReelProject, at: TimeInterval)] = [:]

    /// All nine of `wheels` as a patch: the row default's write.
    static func whole(_ wheels: ColorWheels) -> ColorWheelsPatch {
        func patch(_ wheel: ColorWheel) -> ColorWheelPatch {
            ColorWheelPatch(x: wheel.x, y: wheel.y, master: wheel.master)
        }
        return ColorWheelsPatch(
            lift: patch(wheels.lift), gamma: patch(wheels.gamma), gain: patch(wheels.gain))
    }

    init(
        binding: InspectorBinding, wheels: @escaping () -> ColorWheels,
        ops: @escaping (ColorWheelsPatch) -> [ReelOp]
    ) {
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false
        setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        setContentCompressionResistancePriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        var previous: NSView?
        for kind in ColorWheelKind.allCases {
            let column = makeColumn(kind, binding: binding, wheels: wheels, ops: ops)
            addSubview(column)
            NSLayoutConstraint.activate([
                column.topAnchor.constraint(equalTo: topAnchor),
                column.bottomAnchor.constraint(equalTo: bottomAnchor),
            ])
            if let previous {
                column.leadingAnchor.constraint(equalTo: previous.trailingAnchor, constant: Self.gap)
                    .isActive = true
                column.widthAnchor.constraint(equalTo: previous.widthAnchor).isActive = true
            } else {
                column.leadingAnchor.constraint(equalTo: leadingAnchor).isActive = true
            }
            previous = column
        }
        previous?.trailingAnchor.constraint(equalTo: trailingAnchor).isActive = true
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ColorWheelsView does not support NSCoder")
    }

    private func makeColumn(
        _ kind: ColorWheelKind, binding: InspectorBinding,
        wheels: @escaping () -> ColorWheels, ops: @escaping (ColorWheelsPatch) -> [ReelOp]
    ) -> NSView {
        func wheel() -> ColorWheel { kind.wheel(wheels()) }
        func push() -> (x: Double, y: Double) { (wheel().x, wheel().y) }
        func master() -> Double { wheel().master }
        let name = kind.title
        let title = InspectorRowLabel(name)
        title.alignment = .center
        // A label hugs at 250, above the stack's pull, and would hold the
        // column to its own width; the column is the row's to size.
        title.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        let disc = ColorWheelControl(
            read: push,
            write: { [weak binding] x, y in
                // A puck sends its wheel's push alone, never the master.
                let moved = ColorWheelPatch(x: x, y: y)
                binding?.liveUpdate(ops(kind.patch(moved)))
            },
            begin: { [weak binding] in binding?.liveBegin() },
            end: { [weak binding] in binding?.liveEnd(name) },
            reset: { [weak binding] in
                binding?.apply(name, ops(kind.patch(ColorWheelPatch(x: 0, y: 0))))
            },
            enabled: { true },
            start: { [weak binding] in
                guard let binding, let x = binding.startValue({ push().x }),
                      let y = binding.startValue({ push().y })
                else { return nil }
                return (x, y)
            },
            now: { [weak binding] in
                guard let binding, let x = binding.nowValue({ push().x }),
                      let y = binding.nowValue({ push().y })
                else { return nil }
                return (x, y)
            })
        let strip = WheelStripControl(
            read: master,
            write: { [weak binding] value in
                binding?.liveUpdate(ops(kind.patch(ColorWheelPatch(master: value))))
            },
            begin: { [weak self, weak binding] in self?.stripBegan(kind, binding: binding) },
            end: { [weak self, weak binding] in
                self?.stripEnded(kind, name: name, binding: binding)
            },
            reset: { [weak self, weak binding] in
                self?.stripReset(
                    kind, name: name, binding: binding,
                    ops: ops(kind.patch(ColorWheelPatch(master: 0))))
            },
            enabled: { true },
            start: { [weak binding] in binding?.startValue(master) },
            now: { [weak binding] in binding?.nowValue(master) })
        let field = OptionFieldControl(
            width: InspectorMetrics.fieldWidth, unit: "", decimals: 2, min: -1, max: 1,
            read: master,
            write: { [weak binding] value in
                binding?.apply(name, ops(kind.patch(ColorWheelPatch(master: value))))
            },
            enabled: { true },
            onEdit: { [weak binding] in binding?.edited() })
        disc.keyed = { [weak self] in self?.keyed() ?? false }
        strip.keyed = { [weak self] in self?.keyed() ?? false }
        discs.append(disc)
        strips.append(strip)

        let column = NSView()
        column.translatesAutoresizingMaskIntoConstraints = false
        for view in [title, disc, strip, field] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            column.addSubview(view)
        }
        // The disc is the column less 4 pt, square, never past `maxDisc`; the
        // fill is a lower priority than the cap so a wide pane stops at 112.
        let fill = disc.widthAnchor.constraint(equalTo: column.widthAnchor, constant: -Self.gap)
        fill.priority = NSLayoutConstraint.Priority(750)
        NSLayoutConstraint.activate([
            title.topAnchor.constraint(equalTo: column.topAnchor),
            title.leadingAnchor.constraint(equalTo: column.leadingAnchor),
            title.trailingAnchor.constraint(equalTo: column.trailingAnchor),
            disc.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 4),
            disc.centerXAnchor.constraint(equalTo: column.centerXAnchor),
            disc.heightAnchor.constraint(equalTo: disc.widthAnchor),
            disc.widthAnchor.constraint(lessThanOrEqualToConstant: Self.maxDisc),
            disc.widthAnchor.constraint(lessThanOrEqualTo: column.widthAnchor),
            fill,
            strip.topAnchor.constraint(equalTo: disc.bottomAnchor, constant: 6),
            strip.leadingAnchor.constraint(equalTo: disc.leadingAnchor),
            strip.trailingAnchor.constraint(equalTo: disc.trailingAnchor),
            strip.heightAnchor.constraint(equalToConstant: 13),
            field.topAnchor.constraint(equalTo: strip.bottomAnchor, constant: 4),
            field.centerXAnchor.constraint(equalTo: column.centerXAnchor),
            field.bottomAnchor.constraint(equalTo: column.bottomAnchor),
        ])
        return column
    }

    // MARK: The strip's double-click (#272)

    /// A strip's press: the handle it starts from, then the live trio.
    private func stripBegan(_ kind: ColorWheelKind, binding: InspectorBinding?) {
        stripStarts[kind] = binding?.document?.project
        stripSteps[kind] = nil
        binding?.liveBegin()
    }

    /// A strip's release: the live trio's end, then the handle it left,
    /// kept only when the gesture registered a step (the handle moved).
    private func stripEnded(_ kind: ColorWheelKind, name: String, binding: InspectorBinding?) {
        binding?.liveEnd(name)
        if let after = binding?.document?.project, after !== stripStarts[kind] {
            stripSteps[kind] = (after, ProcessInfo.processInfo.systemUptime)
        }
        stripStarts[kind] = nil
    }

    /// A strip's double-click: the reset amends the step its first click
    /// left when that release is within the double-click interval — so an
    /// earlier gesture's step is never reused — and is its own step
    /// otherwise.
    private func stripReset(
        _ kind: ColorWheelKind, name: String, binding: InspectorBinding?, ops: [ReelOp]
    ) {
        let last = stripSteps.removeValue(forKey: kind)
        if let last,
            ProcessInfo.processInfo.systemUptime - last.at <= NSEvent.doubleClickInterval
        {
            binding?.amend(name, ops, step: last.step)
        } else {
            binding?.apply(name, ops)
        }
    }
}
import AppKit

// MARK: - The master strip

/// A wheel's `master`, −1…1: the slider's look (a 3 pt rail, the 7 × 11 block
/// knob, the accent fill from the LEFT end as Light's ±1 rows have), dragged
/// as a live edit. A press off the knob jumps to the pointer like every
/// inspector slider; one on the knob grabs it where it stands, so the first
/// click of a double-click there writes nothing; ⌥ held drags RELATIVE at a
/// tenth (no jump); a double-click resets the master (`reset`), ONE undo step
/// on or off the knob — off it, `ColorWheelsView` undoes the first click's
/// jump before the reset (#272). Keyed, the fill is the action ink from the action's
/// start value and the knob is in action ink; a coral tick marks the
/// playhead's value when it differs. `press`, `drag` and `release` are the
/// mouse handlers' bodies, internal so a probe drives the gesture.
final class WheelStripControl: NSView, OptionControl {
    private static let rail = InspectorRail(lower: -1, upper: 1)

    private let read: () -> Double
    private let write: (Double) -> Void
    private let begin: () -> Void
    private let end: () -> Void
    private let reset: () -> Void
    private let enabled: () -> Bool
    private let start: () -> Double?
    private let now: () -> Double?
    var keyed: () -> Bool = { false }
    private var isActive = true
    /// The value being dragged and the pointer's last x; nil between
    /// gestures.
    private var dragged: Double?
    private var lastX: CGFloat = 0
    /// The pointer's offset from the knob's centre when a press grabbed the
    /// knob; 0 after a jump.
    private var grab: CGFloat = 0

    init(
        read: @escaping () -> Double, write: @escaping (Double) -> Void,
        begin: @escaping () -> Void, end: @escaping () -> Void, reset: @escaping () -> Void,
        enabled: @escaping () -> Bool, start: @escaping () -> Double?,
        now: @escaping () -> Double?
    ) {
        self.read = read
        self.write = write
        self.begin = begin
        self.end = end
        self.reset = reset
        self.enabled = enabled
        self.start = start
        self.now = now
        super.init(frame: .zero)
        wantsLayer = true
        translatesAutoresizingMaskIntoConstraints = false
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("WheelStripControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: 13)
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        needsDisplay = true
    }

    private var span: CGFloat { Self.rail.span(width: bounds.width) }

    /// The knob's centre for `raw`, the x `draw` puts it at.
    private func knobX(of raw: Double) -> CGFloat {
        Self.rail.knobX(of: raw, width: bounds.width)
    }

    func value(atX x: CGFloat) -> Double { Self.rail.value(atX: x, width: bounds.width) }

    // MARK: Gesture

    /// A press at `x`: a double-click resets; ⌥ (`fine`) begins a relative
    /// drag from the value as it stands; a press on the knob grabs it with
    /// no write; otherwise the value jumps to `x`.
    func press(atX x: CGFloat, fine: Bool, clickCount: Int = 1) {
        guard isActive else { return }
        if clickCount >= 2 {
            dragged = nil
            reset()
            return
        }
        guard dragged == nil else { return }
        begin()
        lastX = x
        grab = 0
        let current = read()
        let offset = x - knobX(of: current)
        if fine {
            dragged = current
        } else if abs(offset) <= InspectorRail.knobSize.width / 2 {
            grab = offset
            dragged = current
        } else {
            let next = value(atX: x)
            dragged = next
            write(next)
        }
        needsDisplay = true
    }

    /// The pointer at `x`: ⌥ moves the value by a tenth of the pointer's
    /// travel since the last event, otherwise it follows the pointer.
    func drag(toX x: CGFloat, fine: Bool) {
        guard let from = dragged else { return }
        let next: Double
        if fine {
            let rail = Self.rail
            let delta = Double((x - lastX) / span) * (rail.upper - rail.lower)
            next = min(max(from + delta * ColorWheelControl.fine, rail.lower), rail.upper)
        } else {
            next = value(atX: x - grab)
        }
        lastX = x
        dragged = next
        write(next)
        needsDisplay = true
    }

    func release() {
        guard dragged != nil else { return }
        dragged = nil
        end()
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        press(atX: convert(event.locationInWindow, from: nil).x,
              fine: event.modifierFlags.contains(.option), clickCount: event.clickCount)
    }

    override func mouseDragged(with event: NSEvent) {
        drag(toX: convert(event.locationInWindow, from: nil).x,
             fine: event.modifierFlags.contains(.option))
    }

    override func mouseUp(with event: NSEvent) {
        release()
    }

    // MARK: Drawing

    override func draw(_ dirtyRect: NSRect) {
        Self.rail.draw(
            in: self, value: dragged ?? read(), start: start(), now: now(), keyed: keyed(),
            keyedKnobInk: DS.action)
    }
}

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        let value = read()
        let amount = hypot(value.x, value.y)
        if amount == 0 {
            toolTip = "Neutral"
        } else {
            var hue = atan2(value.y, value.x) * 180 / .pi
            if hue < 0 { hue += 360 }
            toolTip = String(format: "Hue %.0f° · %.2f", hue.rounded() == 360 ? 0 : hue, amount)
        }
        needsDisplay = true
    }

    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        needsDisplay = true
    }

    // MARK: Geometry

    /// The disc's radius in points: the square's half less the frame's
    /// pixel, so one radius of pointer travel is the full push.
    var radius: CGFloat { max(min(bounds.width, bounds.height) / 2 - 1, 1) }
    private var center: NSPoint { NSPoint(x: bounds.midX, y: bounds.midY) }

    /// A model point (red +x) where it is drawn: turned by `hueRotation`.
    func screenPoint(_ x: Double, _ y: Double) -> NSPoint {
        let angle = Self.hueRotation * .pi / 180
        let sx = x * cos(angle) - y * sin(angle)
        let sy = x * sin(angle) + y * cos(angle)
        return NSPoint(x: center.x + CGFloat(sx) * radius, y: center.y + CGFloat(sy) * radius)
    }

    /// A push clamped onto the rim: divided by its `hypot` when it is past it.
    static func clamped(_ x: Double, _ y: Double) -> (x: Double, y: Double) {
        guard x * x + y * y > 1 else { return (x, y) }
        let r = hypot(x, y)
        return (x / r, y / r)
    }

    // MARK: Gesture

    /// A press at `point` (view coordinates): a double-click resets the push;
    /// otherwise the gesture begins from the push as it stands.
    func press(at point: NSPoint, clickCount: Int = 1) {
        guard isActive else { return }
        if clickCount >= 2 {
            dragged = nil
            reset()
            return
        }
        guard dragged == nil else { return }
        dragged = read()
        last = point
        begin()
        needsDisplay = true
    }

    /// The pointer at `point`: the push moves by the delta since the last
    /// one, turned back into the model's axes, a tenth of it when `fine`.
    func drag(to point: NSPoint, fine: Bool) {
        guard let from = dragged else { return }
        let scale = (fine ? Self.fine : 1) / Double(radius)
        let dx = Double(point.x - last.x) * scale
        let dy = Double(point.y - last.y) * scale
        last = point
        let angle = -Self.hueRotation * .pi / 180
        let mx = dx * cos(angle) - dy * sin(angle)
        let my = dx * sin(angle) + dy * cos(angle)
        let next = Self.clamped(from.x + mx, from.y + my)
        dragged = next
        write(next.x, next.y)
        needsDisplay = true
    }

    func release() {
        guard dragged != nil else { return }
        dragged = nil
        // Ends the gesture even when nothing moved: the document registers no
        // undo step for an unchanged handle.
        end()
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        press(at: convert(event.locationInWindow, from: nil), clickCount: event.clickCount)
    }

    override func mouseDragged(with event: NSEvent) {
        drag(to: convert(event.locationInWindow, from: nil),
             fine: event.modifierFlags.contains(.option))
    }

    override func mouseUp(with event: NSEvent) {
        release()
    }

    // MARK: Drawing

    override func draw(_ dirtyRect: NSRect) {
        let side = min(bounds.width, bounds.height)
        guard side > 4 else { return }
        let square = NSRect(
            x: bounds.midX - side / 2, y: bounds.midY - side / 2, width: side, height: side)
        if let image = discImage(side: side) {
            NSGraphicsContext.current?.cgContext.draw(image, in: square.insetBy(dx: 1, dy: 1))
        }
        // The crosshair, 1 pt, through the neutral centre.
        DS.border.setFill()
        let c = backingAlignedRect(
            NSRect(x: center.x - 0.5, y: center.y - 0.5, width: 1, height: 1),
            options: .alignAllEdgesNearest)
        NSRect(x: square.minX + 1, y: c.minY, width: side - 2, height: 1).fill()
        NSRect(x: c.minX, y: square.minY + 1, width: 1, height: side - 2).fill()
        // The 1 pt square frame.
        DS.border.setStroke()
        let frame = NSBezierPath(rect: square.insetBy(dx: 0.5, dy: 0.5))
        frame.lineWidth = 1
        frame.stroke()

        let value = dragged ?? read()
        let isKeyed = keyed()
        // Keyed: a hollow square at the action's start value.
        if isKeyed, let from = start() {
            DS.action.setStroke()
            let hollow = NSBezierPath(rect: puckRect(at: screenPoint(from.x, from.y)).insetBy(
                dx: 0.5, dy: 0.5))
            hollow.lineWidth = 1
            hollow.stroke()
        }
        // The playhead's value, a coral mark, when it is not where the puck is.
        if let at = now(), hypot(at.x - value.x, at.y - value.y) > 0.001 {
            DS.playhead.setFill()
            puckRect(at: screenPoint(at.x, at.y)).insetBy(dx: 2, dy: 2).fill()
        }
        let puck = puckRect(at: screenPoint(value.x, value.y))
        DS.chromeBackground.setFill()
        puck.insetBy(dx: -1, dy: -1).fill()
        (isKeyed ? DS.action : DS.textStrong).setFill()
        puck.fill()
    }

    private func puckRect(at point: NSPoint) -> NSRect {
        backingAlignedRect(
            NSRect(x: point.x - Self.puck / 2, y: point.y - Self.puck / 2,
                   width: Self.puck, height: Self.puck),
            options: .alignAllEdgesNearest)
    }

    /// The hue disc at this view's pixel size and appearance, from the cache
    /// when both match.
    private func discImage(side: CGFloat) -> CGImage? {
        let scale = window?.backingScaleFactor ?? NSScreen.main?.backingScaleFactor ?? 2
        let pixels = max(Int(((side - 2) * scale).rounded()), 2)
        let dark = effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
        if let disc, disc.pixels == pixels, disc.dark == dark { return disc.image }
        var well: (CGFloat, CGFloat, CGFloat) = (0.5, 0.5, 0.5)
        effectiveAppearance.performAsCurrentDrawingAppearance {
            if let color = NSColor.controlBackgroundColor.usingColorSpace(.sRGB) {
                well = (color.redComponent, color.greenComponent, color.blueComponent)
            }
        }
        guard let image = Self.renderDisc(
            pixels: pixels, ring: Self.ring * scale, well: well)
        else { return nil }
        disc = (image, pixels, dark)
        return image
    }

    /// The fully saturated hue at `degrees` on the HSV ramp (0° red).
    private static func hueRGB(_ degrees: Double) -> (Double, Double, Double) {
        func channel(_ offset: Double) -> Double {
            let t = (degrees / 60 + offset).truncatingRemainder(dividingBy: 6)
            return min(max(abs((t < 0 ? t + 6 : t) - 3) - 1, 0), 1)
        }
        return (channel(0), channel(4), channel(2))
    }

24:| Wheels | Every gradable clip |
25-| Curves | Every gradable clip |
26-| Look | Every gradable clip |
27-
28-Each section's header shows a short summary, such as "neutral", "adjusted", "Warm 80%" or "hue · sat · inverted", and has a **Reset** button that returns only that section to neutral. If no section is open, the tab opens the first one you haven't closed yourself.
29-
30-**Working on several clips.** A control writes only the setting it governs. Dragging Exposure across three clips changes their exposure and leaves each clip's other values alone. When the selected clips have different values, the row shows a mixed badge.
31-
32-**Undo.** Dragging a slider is one undo step, and so is a typed value. Each step is named after its control, for example **Undo Exposure**, **Undo Hue** or **Undo Strength**. A section's **Reset** is one step named after the section ("Light", "Color", "Look", "Adjustment", "Qualifier").
33-
34:The order the grade is applied in is fixed: Color first, then Light, Wheels, Curves (tone curves, then the hue curves) and the Look. The clip's filters from the Picture tab's **Filters** section split around the grade: Pixelate, Blur and Sharpen act on the picture before it, and Sepia, Noir, Vignette and Invert act after the Look, in the order of their slots. That matters when you combine a filter such as Noir or Vignette with a grade. A camera-log conversion set on the media comes before all of them (see [HDR and colour management](hdr-and-color.md)).
